  useEffect(()=>{if(!order?.id)return;let active=true;supabase.from('boletas_entrada').select('id,codigo,boleta_rendimientos(producto,calidad,kg_resultado,paga_productor,cajas,presentacion_kg,kg_manual,orden_venta_linea_id)').eq('orden_compra_id',order.id).then(({data})=>{if(active)setYieldDetails((data||[]).flatMap(b=>(b.boleta_rendimientos||[]).map(r=>({...r,boleta:b.codigo,boleta_id:b.id}))))});return()=>{active=false}},[order?.id])
  useEffect(()=>{if(!order?.id)return;let active=true;supabase.from('boletas_entrada').select('id,codigo,fecha_hora,fin_proceso,finalizada_en').eq('orden_compra_id',order.id).order('fecha_hora').then(({data})=>{if(active)setLinkedReceipts(data||[])});return()=>{active=false}},[order?.id])
  useEffect(()=>{if(!stagedPie||!linkedReceipts.length){setReceiptCosts([]);return}let active=true;supabase.from('costos_boleta_en_pie').select('boleta_id,tipo,monto,proveedores(nombre)').in('boleta_id',linkedReceipts.map(b=>b.id)).then(({data})=>{if(active)setReceiptCosts(data||[])});return()=>{active=false}},[stagedPie,linkedReceipts])
