  useEffect(()=>{if(!order?.id)return;let active=true;supabase.from('ventas_externas_en_pie').select('*').eq('orden_compra_id',order.id).order('fecha').then(({data})=>{if(active)setDirectSales(data||[])});return()=>{active=false}},[order?.id])
  useEffect(()=>{const ids=[...new Set(yieldDetails.map(r=>r.orden_venta_linea_id).filter(Boolean))];if(!ids.length){setSaleLines({});return}let active=true;supabase.from('ordenes_venta_lineas').select('id,precio_caja,precio_quintal,ordenes_venta(moneda,finalizada_en)').in('id',ids).then(({data,error:loadError})=>{if(active&&!loadError)setSaleLines(Object.fromEntries((data||[]).map(line=>[line.id,line])))});return()=>{active=false}},[yieldDetails])
  const yieldPrice=quality=>form.producto!=='Yuca'?'precio_campo':quality==='Exportable Europa'?'precio_europa':quality==='Exportable estadounidense'?'precio_eeuu':quality==='Segunda gruesa'?'precio_segunda_gruesa':quality==='Segunda menuda'?'precio_segunda_menuda':quality.startsWith('Rechazo')?'precio_rechazo':null
  const pieYucaKg=yieldDetails.reduce((sum,r)=>sum+Number(r.kg_resultado||0),0)
